// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public { c = new Size(); }

    function testFuzz_property(bytes32 role, address attacker, address victim) public {
        // caller must differ from the confirmation account: the check only bites cross-account calls
        vm.assume(attacker != address(0));
        vm.assume(victim != address(0));
        vm.assume(attacker != victim);

        // Rule: a call to renounceRole(role, Y) by X is admissible ONLY when X == Y.
        // For X != Y the reference reverts with AccessControlBadConfirmation;
        // the mutant drops the check and the call completes without reverting.

        // Cross-account: must revert on the reference.
        vm.prank(attacker);
        bool okCross;
        try c.renounceRole(role, victim) { okCross = true; } catch { okCross = false; }

        // Self renounce: must succeed on the reference.
        vm.prank(attacker);
        bool okSelf;
        try c.renounceRole(role, attacker) { okSelf = true; } catch { okSelf = false; }

        // exactly one assertion over c's observable surface
        assertTrue(okSelf && !okCross, "renounceRole must only confirm the caller's own account");
    }
}
